questionvariables.text:
/* Fixed. questionsimplify 0 so that the given first line and the written-out sum stay as typed. */
strip_eq(L) := if safe_op(L) = "stackeq" then first(args(L)) else L;
ta1: [(n+2)*(n+3)-n*(n+1), stackeq(n^2+5*n+6-n^2-n), stackeq(4*n+6), stackeq(n+(n+1)+(n+2)+(n+3))];
sumex: n+(n+1)+(n+2)+(n+3);
/* cval only chooses the wording of the correct-answer feedback; the "jumps" check is in the PRT's feedback variables. */
cval: 4*n+6;
/* Diagnostic: the sign slip -n(n + 1) = -n^2 + n gives 6n + 6. */
slipval: 6*n+6;

feedbackvariables.text:
lastex: strip_eq(last(ans1));
firstex: first(ta1);
/* newlines: the lines after the first that do more than restate the first line (EqualComAss, as stack_equiv_find_step uses). */
newlines: sublist(rest(ans1), lambda([L], emptyp(stack_equiv_find_step(L, [firstex]))));
/* The working jumps when the first such line is already the sum written out. Any other line there counts as working. */
jumps: if emptyp(newlines) then false else not(emptyp(stack_equiv_find_step(first(newlines), [sumex])));
shown: not(jumps);
nowork: emptyp(newlines);
hasval: not(emptyp(stack_equiv_find_step(cval, ans1)));
hasslip: some(lambda([L], is(ev(expand(strip_eq(L) - slipval), simp) = 0)), ans1);
